package com.example.ts15quarkusbanking.domain;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Domain kernel for "Ejecución de pagos entre cuentas (BIAN Payment Execution)" (generated by gherkin-ai).
 * Pure domain logic: no framework, no I/O. Extend the command handlers with your business rules.
 */
public class PaymentExecutionAggregate {
    private final String id;
    private PaymentExecutionState state = PaymentExecutionState.PENDING;
    private long version;
    private final List<PaymentExecutionDomainEvent> pendingEvents = new ArrayList<>();

    public PaymentExecutionAggregate(String id) {
        if (id == null || id.isBlank()) throw new DomainValidationException("PaymentExecution id is required");
        this.id = id;
    }

    /** Rebuilds an aggregate from persisted state; no events are recorded. */
    public static PaymentExecutionAggregate restore(String id, PaymentExecutionState state, long version) {
        var aggregate = new PaymentExecutionAggregate(id);
        aggregate.state = state;
        aggregate.version = version;
        return aggregate;
    }

    public String getId() { return id; }
    public PaymentExecutionState getState() { return state; }
    public long getVersion() { return version; }

    /** Events recorded since the aggregate was loaded (to be saved via the outbox). */
    public List<PaymentExecutionDomainEvent> getPendingEvents() { return Collections.unmodifiableList(pendingEvents); }

    public PaymentExecutionDomainEvent processPaymentExecution(PaymentExecutionCommand command) {
        assertValid(command);
        return record(PaymentExecutionEventType.SePublicaEventoPaymentExecuted, command.payload());
    }

    private void assertValid(PaymentExecutionCommand command) {
        if (command == null || command.id() == null || command.id().isBlank()) throw new DomainValidationException("Command id is required");
        if (!command.id().equals(id)) throw new DomainValidationException("Command targets " + command.id() + ", not " + id);
    }

    private PaymentExecutionDomainEvent record(PaymentExecutionEventType type, Map<String, Object> payload) {
        version += 1;
        var event = new PaymentExecutionDomainEvent(type, id, version, Instant.now(), payload == null ? Map.of() : payload);
        pendingEvents.add(event);
        return event;
    }
}
